-- PostgreSQL 15+; synthetic proposal and grant metadata only.
CREATE SCHEMA IF NOT EXISTS innovation_demo;
CREATE TABLE IF NOT EXISTS innovation_demo.calls(call_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,call_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,focus_area TEXT NOT NULL,opens_on DATE NOT NULL,closes_on DATE NOT NULL,budget_ceiling_ugx NUMERIC(18,2) CHECK(budget_ceiling_ugx IS NULL OR budget_ceiling_ugx>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','closed','awarding','complete')),CHECK(closes_on>=opens_on));
CREATE TABLE IF NOT EXISTS innovation_demo.proposals(proposal_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,proposal_ref TEXT NOT NULL UNIQUE,call_id BIGINT NOT NULL REFERENCES innovation_demo.calls(call_id) ON DELETE RESTRICT,applicant_token TEXT NOT NULL,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),requested_budget_ugx NUMERIC(18,2) NOT NULL CHECK(requested_budget_ugx>=0),status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN('draft','submitted','under_review','accepted','declined','withdrawn')),review_note TEXT,UNIQUE(call_id,applicant_token));
CREATE TABLE IF NOT EXISTS innovation_demo.projects(project_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_ref TEXT NOT NULL UNIQUE,proposal_id BIGINT NOT NULL UNIQUE REFERENCES innovation_demo.proposals(proposal_id) ON DELETE RESTRICT,approved_budget_ugx NUMERIC(18,2) NOT NULL CHECK(approved_budget_ugx>=0),start_date DATE,end_date DATE,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','active','blocked','completed','cancelled')),CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date));
CREATE TABLE IF NOT EXISTS innovation_demo.milestones(milestone_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,milestone_ref TEXT NOT NULL UNIQUE,project_id BIGINT NOT NULL REFERENCES innovation_demo.projects(project_id) ON DELETE RESTRICT,title TEXT NOT NULL,due_date DATE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','completed','cancelled')),evidence_ref TEXT,completed_at TIMESTAMPTZ,CHECK(status<>'completed' OR completed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS innovation_demo.milestone_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,milestone_id BIGINT NOT NULL REFERENCES innovation_demo.milestones(milestone_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','completed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_innovation_proposal_call_status ON innovation_demo.proposals(call_id,status,submitted_at DESC);
CREATE INDEX IF NOT EXISTS ix_innovation_milestone_due ON innovation_demo.milestones(status,due_date) WHERE status NOT IN('completed','cancelled');
CREATE INDEX IF NOT EXISTS ix_innovation_events ON innovation_demo.milestone_events(milestone_id,happened_at DESC,event_id DESC);